import{_ as e,o as t,c as s,f as a}from"./index.fb8fc4c4.js";const c=a('<div class="flex items-center p-4 md:px-10 lg:px-20" data-v-c6f7c660><div class="p-4 md:px-10 lg:px-20" data-v-c6f7c660><h1 class="text-center text-3xl md:text-4xl leading-none font-extrabold tracking-tight" data-v-c6f7c660> Etude de march\xE9 sectoriel </h1><p class="text-md md:text-lg tracking-tight leading-7 text-subtitlegray mt-6" data-v-c6f7c660> L&#39;\xE9tude de march\xE9 est un passage oblig\xE9 pour tout projet d&#39;entreprise. Elle vous apporte les r\xE9ponses adapt\xE9es et vous sert \xE0 mieux connaitre le secteur d&#39; activit\xE9, la zone de chalandise et l&#39;environnement de votre future entreprise. La CCI-B\xE9nin vous accompagne pour l&#39;implantation de vos commerces de votre industrie et de vos services. </p></div></div><div class="p-4 md:px-10 lg:px-20" data-v-c6f7c660><div class="pt-16 pb-8" data-v-c6f7c660><h1 class="text-3xl md:text-4xl leading-none font-extrabold tracking-tight" data-v-c6f7c660>Objectifs</h1><p class="text-sm sm:text-lg tracking-tight leading-4 md:leading-7 text-subtitlegray mt-3" data-v-c6f7c660> Nous vous aidons \xE0 identifier les secteurs porteurs en vous fournissant les informations n\xE9c\xE9ssaires pour r\xE9aliser une analyse sectorielle de votre march\xE9 cible. </p></div><div class="flex flex-wrap grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 md:gap-8 pb-20" data-v-c6f7c660><div class="p-6 rounded-lg bg-gris mb-2 md:mb-0" data-v-c6f7c660><svg width="48" height="48" viewBox="0 0 48 48" fill="none" xmlns="http://www.w3.org/2000/svg" data-v-c6f7c660><rect width="48" height="48" rx="8" fill="#FAE8E0" data-v-c6f7c660></rect><path d="M21 24L23 26L27 22M33 24C33 28.9706 28.9706 33 24 33C19.0294 33 15 28.9706 15 24C15 19.0294 19.0294 15 24 15C28.9706 15 33 19.0294 33 24Z" stroke="#DD7A4B" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" data-v-c6f7c660></path></svg><div class="mt-6" data-v-c6f7c660><h4 class="text-lg leading-7 font-medium text-borderSimple" data-v-c6f7c660> Explorer les grandes tendances du march\xE9 et ses acteurs </h4><p class="text-sm leading-5 text-subtitlegray" data-v-c6f7c660> Utilisez les donn\xE9es fournies par la CCI-B\xE9nin pour identifier les tendances en termes de croissance, le niveau d\u2019attractivit\xE9 du secteur, l\u2019\xE9volution des entreprises et leur marge commerciale. </p></div></div><div class="p-6 rounded-lg bg-gris" data-v-c6f7c660><svg width="48" height="48" viewBox="0 0 48 48" fill="none" xmlns="http://www.w3.org/2000/svg" data-v-c6f7c660><rect width="48" height="48" rx="8" fill="#FAE8E0" data-v-c6f7c660></rect><path d="M21 24L23 26L27 22M33 24C33 28.9706 28.9706 33 24 33C19.0294 33 15 28.9706 15 24C15 19.0294 19.0294 15 24 15C28.9706 15 33 19.0294 33 24Z" stroke="#DD7A4B" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" data-v-c6f7c660></path></svg><div class="mt-6" data-v-c6f7c660><h4 class="text-lg leading-7 font-medium text-borderSimple" data-v-c6f7c660> D\xE9couvrir les consommateurs, les acheteurs et les concurrents </h4><p class="text-sm leading-5 text-subtitlegray" data-v-c6f7c660> Anticipez les grands mouvements du secteurs pour d\xE9terminer le positionnement le plus optimum pour votre entreprise \xE0 partir des profils des consommateurs et leurs habitudes de consommation. </p></div></div><div class="p-6 rounded-lg bg-gris" data-v-c6f7c660><svg width="48" height="48" viewBox="0 0 48 48" fill="none" xmlns="http://www.w3.org/2000/svg" data-v-c6f7c660><rect width="48" height="48" rx="8" fill="#FAE8E0" data-v-c6f7c660></rect><path d="M21 24L23 26L27 22M33 24C33 28.9706 28.9706 33 24 33C19.0294 33 15 28.9706 15 24C15 19.0294 19.0294 15 24 15C28.9706 15 33 19.0294 33 24Z" stroke="#DD7A4B" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" data-v-c6f7c660></path></svg><div class="mt-6" data-v-c6f7c660><h4 class="text-lg leading-7 font-medium text-borderSimple" data-v-c6f7c660> Identifier les contraintes et les opportunit\xE9s de votre secteur d&#39;activit\xE9 </h4><p class="text-sm leading-5 text-subtitlegray" data-v-c6f7c660> Obtenez une vision compl\xE8te des diff\xE9rentes opportunit\xE9s \xE0 d\xE9velopper et ds contraintes sp\xE9cifiques susceptibles d\u2019influencer le developpement de vos activit\xE9s commerciales. </p></div></div></div><div class="flex items-center flex-wrap grid grid-cols-1 lg:grid-cols-2 gap-6 md:gap-8 pb-8 md:pb-20" data-v-c6f7c660><div class="asset-session hidden lg:flex" data-v-c6f7c660></div><div data-v-c6f7c660><h2 class="text-3xl tracking-tight font-extrabold leading-9 text-gray-900 sm:text-3xl" data-v-c6f7c660> Vous b\xE9n\xE9ficiez de nos donn\xE9es <br data-v-c6f7c660> locales et notre exclusivit\xE9 </h2><p class="my-3 leading-7 text-lg text-subtitlegray sm:my-4" data-v-c6f7c660> La CCI-B\xE9nin accompagne les entreprises b\xE9ninoises dans leur d\xE9marche d\u2019analyse sectorielle. Gr\xE2ce \xE0 cette exp\xE9rience et \xE0 notre excellent r\xE9seau national, nous disposons des chiffres actuels, exclusifs concernant votre march\xE9, les profils des consommateurs et concurrents. Autrement dit, nous vous donnons acc\xE8s \xE0 des donn\xE9es d&#39;enqu\xEAtes pr\xE9cieuses sur le comportement d&#39;achat local. </p></div></div><div class="flex items-center flex-wrap grid grid-cols-1 lg:grid-cols-2 gap-6 md:gap-8 pb-8 md:pb-20" data-v-c6f7c660><div data-v-c6f7c660><h2 class="text-3xl tracking-tight font-extrabold leading-9 text-gray-900 sm:text-3xl" data-v-c6f7c660> Vous obtenez rapidement une \xE9tude <br data-v-c6f7c660> de march\xE9 compl\xE8te et objective </h2><p class="my-3 leading-7 text-lg text-subtitlegray sm:my-4" data-v-c6f7c660> Quelques semaines apr\xE8s votre commande, vous pouvez acc\xE9der \xE0 un rapport complet. Nos \xE9tudes de march\xE9 sont bas\xE9es sur notre forte connaissance en amont des projets votre zone de chalandise commerciale. Le document qui vous est soumis constitue une 1\xE8re \xE9tape de r\xE9flexion pour organiser votre projet d&#39;entreprise. Nous concluons cette \xE9tude marketing par des pr\xE9conisations objectives et qualifi\xE9es avec des partenaires. </p></div><div class="asset-session hidden lg:flex" data-v-c6f7c660></div></div><div class="flex items-center flex-wrap grid grid-cols-1 lg:grid-cols-2 gap-6 md:gap-8 pb-8 md:pb-20" data-v-c6f7c660><div class="asset-session hidden lg:flex" data-v-c6f7c660></div><div data-v-c6f7c660><h2 class="text-3xl tracking-tight font-extrabold leading-9 text-gray-900 sm:text-3xl" data-v-c6f7c660> Vous recevez des \xE9l\xE9ments concrets <br data-v-c6f7c660> pour pr\xE9parer votre business plan </h2><p class="my-3 leading-7 text-lg text-subtitlegray sm:my-4" data-v-c6f7c660> Outre les chiffres cl\xE9s de votre secteur d&#39;activit\xE9, l&#39;\xE9tude de march\xE9 \xE9tablie par la CCI-B\xE9nin vous permet de calculer votre chiffre d&#39;affaires potentiel, en pr\xE9paration de votre business plan. </p></div></div></div>',2),i=[c],d={__name:"etude-marches",setup(r){return(n,l)=>(t(),s("main",null,i))}},v=e(d,[["__scopeId","data-v-c6f7c660"]]);export{v as default};
